def to_json(v):
    if v is None:
        return "null"
    if v is True:
        return "true"
    if v is False:
        return "false"
    if isinstance(v, (int, float)):
        return repr(v)
    if isinstance(v, str):
        s = v.replace(chr(92), chr(92) + chr(92)).replace(chr(34), chr(92) + chr(34)).replace(chr(10), " ").replace(chr(13), " ").replace(chr(9), " ")
        return '"' + s + '"'
    if isinstance(v, dict):
        return "{" + ",".join(to_json(str(k)) + ":" + to_json(val) for k, val in v.items()) + "}"
    if isinstance(v, (list, tuple)):
        return "[" + ",".join(to_json(x) for x in v) + "]"
    return to_json(str(v))


SAFE_CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_.~"

def url_encode(s):
    out_chars = []
    for b in s.encode("utf-8"):
        ch = chr(b)
        if ch in SAFE_CHARS:
            out_chars.append(ch)
        else:
            out_chars.append("%" + format(b, "02X"))
    return "".join(out_chars)


