def text(v):
    return str(v or "").strip().lower()

def tokens(v):
    out = []
    cur = ""
    for ch in text(v):
        if ("a" <= ch <= "z") or ("0" <= ch <= "9") or ch in "+#.":
            cur += ch
        else:
            if cur:
                out.append(cur)
                cur = ""
    if cur:
        out.append(cur)
    return set(out)

def arr(v):
    if isinstance(v, list):
        return [text(x) for x in v if text(x)]
    if v in (None, ""):
        return []
    parts = []
    cur = ""
    for ch in str(v):
        if ch in ",;|\n":
            if cur.strip():
                parts.append(cur.strip())
            cur = ""
        else:
            cur += ch
    if cur.strip():
        parts.append(cur.strip())
    return [text(x) for x in parts if text(x)]

def date_ordinal(y, m, d):
    y -= 1 if m <= 2 else 0
    era = y // 400
    yoe = y - era * 400
    mp = m + (-3 if m > 2 else 9)
    doy = (153 * mp + 2) // 5 + d - 1
    doe = yoe * 365 + yoe // 4 - yoe // 100 + doy
    return era * 146097 + doe

def date_parts(s):
    s = str(s or "").strip()
    if len(s) >= 10 and s[4] == "-" and s[7] == "-":
        try:
            return int(s[0:4]), int(s[5:7]), int(s[8:10])
        except Exception:
            return None
    for sep in ("-", "/"):
        p = s.split(sep)
        if len(p) == 3:
            try:
                a, b, c = [int(x) for x in p]
                if len(p[0]) == 4:
                    return a, b, c
                if a > 12:
                    return c, b, a
                return c, a, b
            except Exception:
                pass
    return None

def posted_age_days(v, today_iso):
    s = text(v)
    if not s:
        return None
    words = s.split()
    if len(words) >= 3 and words[0].isdigit() and words[2].startswith("ago"):
        n = int(words[0])
        unit = words[1].rstrip("s")
        mult = {"minute":0, "hour":0, "day":1, "week":7, "month":30}
        if unit in mult:
            return mult[unit] * n
    p = date_parts(s)
    today = date_parts(today_iso)
    if p and today:
        return max(0, date_ordinal(*today) - date_ordinal(*p))
    return None

def recency_score(v, today_iso):
    age = posted_age_days(v, today_iso)
    if age is None: return 50.0
    if age <= 3: return 100.0
    if age <= 7: return 90.0
    if age <= 14: return 80.0
    if age <= 30: return 65.0
    if age <= 60: return 45.0
    if age <= 90: return 30.0
    return 15.0

def relevance_score(job, resume):
    title = text(job.get("job_title"))
    roles = arr(resume.get("target_job_roles"))
    role_scores = []
    tt = tokens(title)
    for role in roles:
        rt = tokens(role)
        if rt and tt:
            role_scores.append((len(rt & tt) / max(1, len(rt))) * 100)
    title_rel = max(role_scores) if role_scores else 50.0

    candidate = set()
    for key in ("technical_skills","programming_languages","data_analytics_tools","skills","tools"):
        candidate.update(tokens(" ".join(arr(resume.get(key)))))

    job_skills = set()
    skills = job.get("skills")
    if isinstance(skills, dict):
        for key in ("required","matched","missing"):
            job_skills.update(tokens(" ".join(arr(skills.get(key)))))
    else:
        job_skills.update(tokens(" ".join(arr(skills))))

    skill_rel = (len(candidate & job_skills) / len(job_skills) * 100) if job_skills else 50.0
    return round(title_rel * 0.6 + skill_rel * 0.4, 2)

